WITH with_window AS (SELECT e.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM orders e INNER JOIN promotions pr ON e.channel = pr.channel AND e.order_date >= pr.starts_on AND e.order_date < pr.ends_on + INTERVAL '30' DAY), with_window_orders AS (SELECT src.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM with_window src INNER JOIN promotions pr ON src.channel <=> pr.channel AND src.order_date >= pr.starts_on AND src.order_date < pr.ends_on + INTERVAL '7' DAY), eligible AS (SELECT s.* FROM with_window_orders s WHERE NOT EXISTS (SELECT 1 FROM shipments x WHERE x.order_id = s.id AND x.shipped_date < s.order_date)), matched AS (SELECT e.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM eligible e LEFT JOIN subscriptions sub ON e.customer_id = sub.customer_id AND e.order_date >= sub.start_date AND e.order_date < sub.end_date + INTERVAL '14' DAY), stats AS (SELECT plan, DATE_TRUNC('YEAR', order_date) AS year_start, SORT_ARRAY(COLLECT_SET(promotion_promo_code)) AS promotion_promo_code_list, SUM(promo_id_2) FILTER (WHERE plan = 'premium') AS premium_total_promo_id_2, COUNT(*) FILTER (WHERE status = 'COMPLETED') AS completed_rows FROM matched GROUP BY CUBE (plan, DATE_TRUNC('YEAR', order_date))) SELECT plan, year_start, promotion_promo_code_list, completed_rows, CASE WHEN plan RLIKE '^(basic|premium)$' THEN 'GROUP_B' WHEN plan RLIKE '^(standard|enterprise)$' THEN 'CORE' ELSE 'PRIORITY' END AS plan_zone FROM stats ORDER BY completed_rows DESC NULLS LAST;
